import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Dashboard — Troubleshooting & FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"dashboard-04-troubleshooting-and-faqs.md","filePath":"dashboard-04-troubleshooting-and-faqs.md"}'),i={name:"dashboard-04-troubleshooting-and-faqs.md"};function n(h,e,s,d,l,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="dashboard-—-troubleshooting-faqs" tabindex="-1">Dashboard — Troubleshooting &amp; FAQs <a class="header-anchor" href="#dashboard-—-troubleshooting-faqs" aria-label="Permalink to &quot;Dashboard — Troubleshooting &amp; FAQs&quot;">​</a></h1><p><em>Common questions about the Dashboard</em></p><hr><h2 id="why-is-the-dashboard-empty" tabindex="-1">Why is the Dashboard empty? <a class="header-anchor" href="#why-is-the-dashboard-empty" aria-label="Permalink to &quot;Why is the Dashboard empty?&quot;">​</a></h2><p>The Dashboard shows recently created and updated objects. If your workspace is new, objects haven&#39;t been created yet. Start by importing a transcript in Extracts, adding features to the backlog, or creating a Roadmap — the Dashboard will fill as you work.</p><p>If you&#39;ve been active but the Dashboard still looks empty, refresh the page. The Dashboard reflects the live state of your workspace.</p><hr><h2 id="why-is-a-specific-object-not-appearing-in-the-dashboard" tabindex="-1">Why is a specific object not appearing in the Dashboard? <a class="header-anchor" href="#why-is-a-specific-object-not-appearing-in-the-dashboard" aria-label="Permalink to &quot;Why is a specific object not appearing in the Dashboard?&quot;">​</a></h2><p>The Dashboard shows a limited number of items per column, sorted by most recently updated. If an object hasn&#39;t been touched recently, it may not appear — even if it exists. Navigate to the relevant module to see a complete list.</p><hr><h2 id="what-does-newer-version-available-mean-in-the-aligning-plans-column" tabindex="-1">What does &quot;Newer version available&quot; mean in the Aligning Plans column? <a class="header-anchor" href="#what-does-newer-version-available-mean-in-the-aligning-plans-column" aria-label="Permalink to &quot;What does &quot;Newer version available&quot; mean in the Aligning Plans column?&quot;">​</a></h2><p>It means the source artifact (a Roadmap, Strategy, or Competitive Intelligence report) has been updated since you last exported or shared it. The people who received the previous version are looking at an older picture.</p><p>Click through to the source artifact, make sure the latest changes are in order, and re-export or reshare it.</p><hr><h2 id="how-does-the-new-item-highlighting-work" tabindex="-1">How does the &quot;new item&quot; highlighting work? <a class="header-anchor" href="#how-does-the-new-item-highlighting-work" aria-label="Permalink to &quot;How does the &quot;new item&quot; highlighting work?&quot;">​</a></h2><p>Items are highlighted as new if they were created or updated after the last time you visited the Dashboard. The system records your last visit timestamp when you load the page — anything newer than that gets the cyan highlight.</p><p>If you&#39;ve just logged in for the first time today, everything updated since your last session counts as new.</p><hr><h2 id="can-i-configure-what-appears-in-each-column" tabindex="-1">Can I configure what appears in each column? <a class="header-anchor" href="#can-i-configure-what-appears-in-each-column" aria-label="Permalink to &quot;Can I configure what appears in each column?&quot;">​</a></h2><p>The columns and what they contain are fixed. You can reorder the columns by dragging, but you cannot add, remove, or filter the objects within each column. For custom views of your objects, use the individual modules (Backlog, Roadmaps, etc.) where filtering and sorting are available.</p><hr><h2 id="can-i-see-the-dashboard-for-a-different-organization" tabindex="-1">Can I see the Dashboard for a different organization? <a class="header-anchor" href="#can-i-see-the-dashboard-for-a-different-organization" aria-label="Permalink to &quot;Can I see the Dashboard for a different organization?&quot;">​</a></h2><p>The Dashboard always shows data for your currently active organization. If you belong to multiple organizations, switch organizations using the organization selector — the Dashboard will reflect the new organization.</p><hr><h2 id="why-do-i-see-fewer-than-the-expected-number-of-items-in-a-column" tabindex="-1">Why do I see fewer than the expected number of items in a column? <a class="header-anchor" href="#why-do-i-see-fewer-than-the-expected-number-of-items-in-a-column" aria-label="Permalink to &quot;Why do I see fewer than the expected number of items in a column?&quot;">​</a></h2><p>Each column has a maximum number of items it shows (varies by column, typically 6–10). If fewer items appear, it means fewer than that number of objects exist or have been recently updated. There is no way to increase the limit — navigate to the module for a full list.</p><hr>',27)])])}const m=a(i,[["render",n]]);export{p as __pageData,m as default};
